window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-85be5229d928b6a2"]={"versions": [{"id": "FIG-85be5229d928b6a2", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Offboard Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über Bus-/Netzwerkschnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle, spezifiziert für <code>CAN, CAN-FD, Ethernet</code>.</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application</code>: Applikation zur Handhabung von Diagnoseanfragen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Strecke (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur <code>Diagnostic Application</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von der <code>Diagnostic Application</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Offboard Diagnostic Client</code> kommuniziert über Ethernet/CAN/DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die <code>Diagnostic Application</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der <code>Diagnostic Application</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert die <code>Diagnostic Application</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass entweder ein Diagnosetester-Pfad via DM oder ein Cloud-Pfad existiert, der Befehle an UCM weiterreicht.</p>"}, {"id": "FIG-05a378b455e1e95b", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server-Cluster, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über eine Schnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle (Port am Fahrzeugrand).</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application / OTA Client</code>: Kombinierte Applikationskomponente zur Handhabung von Diagnoseanfragen und Over-the-Air-Aktualisierungen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Verbindung (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application / OTA Client</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von <code>Diagnostic Application / OTA Client</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Diagnostic Client</code> kommuniziert über DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die Komponente <code>Diagnostic Application / OTA Client</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert <code>Diagnostic Application / OTA Client</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application / OTA Client</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass eine Applikationsinstanz existiert, welche die Diagnose- oder OTA-Schnittstellen bedient und die Update-Vorgänge über die UCM-Dienstschnittstelle anstößt.</p>"}, {"id": "FIG-0d53791d62cba4bd", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server-Cluster, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über eine Schnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle (Port am Fahrzeugrand).</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application / OTA Client</code>: Kombinierte Applikationskomponente zur Handhabung von Diagnoseanfragen und Over-the-Air-Aktualisierungen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Verbindung (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application / OTA Client</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von <code>Diagnostic Application / OTA Client</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Diagnostic Client</code> kommuniziert über DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die Komponente <code>Diagnostic Application / OTA Client</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert <code>Diagnostic Application / OTA Client</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application / OTA Client</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass eine Applikationsinstanz existiert, welche die Diagnose- oder OTA-Schnittstellen bedient und die Update-Vorgänge über die UCM-Dienstschnittstelle anstößt.</p>"}, {"id": "FIG-a621a6f5c59374d8", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server-Cluster, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über eine Schnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle (Port am Fahrzeugrand).</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application / OTA Client</code>: Kombinierte Applikationskomponente zur Handhabung von Diagnoseanfragen und Over-the-Air-Aktualisierungen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Verbindung (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application / OTA Client</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von <code>Diagnostic Application / OTA Client</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Diagnostic Client</code> kommuniziert über DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die Komponente <code>Diagnostic Application / OTA Client</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert <code>Diagnostic Application / OTA Client</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application / OTA Client</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass eine Applikationsinstanz existiert, welche die Diagnose- oder OTA-Schnittstellen bedient und die Update-Vorgänge über die UCM-Dienstschnittstelle anstößt.</p>"}, {"id": "FIG-19e42b923cfed040", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server-Cluster, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über eine Schnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle (Port am Fahrzeugrand).</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application / OTA Client</code>: Kombinierte Applikationskomponente zur Handhabung von Diagnoseanfragen und Over-the-Air-Aktualisierungen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Verbindung (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application / OTA Client</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von <code>Diagnostic Application / OTA Client</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Diagnostic Client</code> kommuniziert über DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die Komponente <code>Diagnostic Application / OTA Client</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert <code>Diagnostic Application / OTA Client</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application / OTA Client</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass eine Applikationsinstanz existiert, welche die Diagnose- oder OTA-Schnittstellen bedient und die Update-Vorgänge über die UCM-Dienstschnittstelle anstößt.</p>"}, {"id": "FIG-efbdb9bac2d02a88", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Architekturübersicht für den Diagnose- und Aktualisierungs-Anwendungsfall in AUTOSAR Adaptive Platform. Dargestellt ist die Systemgrenze des Gesamtfahrzeugs („Vehicle“) mit einem Steuergerät („«device» Adaptive ECU“) sowie die Anbindung an externe Instanzen („Cloud“, „Server“ und „Offboard Diagnostic Client“). Das Diagramm gliedert die Plattform in zwei Schichten: den „AUTOSAR Adaptive Application Layer“ und die darunterliegende Ebene „AUTOSAR Adaptive Platform Services + Foundation“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Offboard-Domäne</strong>:</li>\n<li><code>Server</code>: Backend-Server-Cluster, bidirektional über eine gestrichelte Verbindung mit der <code>Cloud</code> gekoppelt.</li>\n<li><code>Cloud</code>: Vermittlungsnetzwerk zwischen Backend und Fahrzeug.</li>\n<li><code>Diagnostic Client</code>: Externes Diagnosegerät (Laptop-Symbol), bidirektional über eine Schnittstelle an das Fahrzeug angebunden.</li>\n<li><strong>Fahrzeuggrenze (<code>Vehicle</code>)</strong>:</li>\n<li>Externe Kommunikationsschnittstelle (Port am Fahrzeugrand).</li>\n<li><strong>Steuergerät (<code>«device» Adaptive ECU</code>)</strong>:</li>\n<li><code>AUTOSAR Adaptive Application Layer</code>:</li>\n<li><code>Diagnostic Application / OTA Client</code>: Kombinierte Applikationskomponente zur Handhabung von Diagnoseanfragen und Over-the-Air-Aktualisierungen.</li>\n<li><code>App A</code>, <code>App B</code>, <code>App ...</code>: Generische adaptive Applikationen.</li>\n<li><code>AUTOSAR Adaptive Platform Services + Foundation</code>:</li>\n<li><code>Diagnostic Manager (DM)</code>: Plattformdienst mit einem <code>DoIP socket</code>-Port.</li>\n<li><code>«ServiceProvider» UCM</code>: Update and Configuration Management als Plattform-Dienstleister.</li>\n<li><strong>Verbindungen & Ports</strong>:</li>\n<li>DoIP-Verbindung: Vom fahrzeugexternen Netzwerkanschluss über eine optionale Verbindung (<code>«optional»</code>) zum <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>.</li>\n<li>Diagnose-Routing: Gestrichelter Pfeil vom <code>Diagnostic Manager (DM)</code> zur Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li>Cloud-Anbindung: Gestrichelter, bidirektionaler Pfeil zwischen <code>Cloud</code> und <code>Diagnostic Application / OTA Client</code>, annotiert mit <code>«optional»</code>.</li>\n<li>UCM-Interaktion: Gestrichelter Pfeil von <code>Diagnostic Application / OTA Client</code> zum Service-Provider <code>UCM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung beschreibt zwei alternative, optionale Pfade zur Einleitung und Durchführung von Software-Updates:</p>\n<ol class=\"fig-list\">\n<li><strong>Onboard-/Offboard-Diagnosepfad</strong>: Ein externer <code>Diagnostic Client</code> kommuniziert über DoIP mit dem <code>DoIP socket</code> des <code>Diagnostic Manager (DM)</code>. Der DM leitet die Diagnosebefehle bzw. Update-Anforderungen intern an die Komponente <code>Diagnostic Application / OTA Client</code> weiter.</li>\n<li><strong>Backend-/Cloud-Pfad (OTA)</strong>: Ein externer <code>Server</code> kommuniziert über die <code>Cloud</code> direkt (optional) mit der Komponente <code>Diagnostic Application / OTA Client</code>.</li>\n<li><strong>UCM-Triggering</strong>: In beiden Szenarien fungiert <code>Diagnostic Application / OTA Client</code> als Vermittler und ruft die Services des <code>UCM</code> («ServiceProvider») auf, um den Update-Prozess auf dem Steuergerät anzustoßen. Das UCM selbst kommuniziert weder direkt mit dem externen Diagnosetester noch mit der Cloud.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das UCM ist als reiner Service-Provider konzipiert und initiiert Software-Updates nicht selbstständig. Ebenso wickelt UCM das Diagnoseprotokoll (UDS) nicht selbst ab und lädt Software-Pakete nicht eigenständig aus der Cloud herunter; diese Aufgaben verbleiben in der Verantwortlichkeit von Applikationen (z. B. <code>Diagnostic Application / OTA Client</code>). Die Anbindungen über DoIP bzw. Cloud sind jeweils als <code>«optional»</code> deklariert. Integratoren müssen sicherstellen, dass eine Applikationsinstanz existiert, welche die Diagnose- oder OTA-Schnittstellen bedient und die Update-Vorgänge über die UCM-Dienstschnittstelle anstößt.</p>"}], "trans": [{"from": "FIG-85be5229d928b6a2", "to": "FIG-05a378b455e1e95b", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Adaptive Application Layer: Komponente „Diagnostic Application“ umbenannt zu „Diagnostic Application / OTA Client“, wodurch der OTA-Anwendungsfall explizit als Software-Entität auf Applikationsebene verankert wird.</li>\n<li>Fahrzeug-Schnittstelle / Diagnose: Beschriftung „CAN, CAN-FD, Ethernet“ an der fahrzeugexternen Schnittstelle entfallen.</li>\n<li>Offboard-Diagnose: Externe Diagnose-Komponente „Offboard Diagnostic Client“ umbenannt zu „Diagnostic Client“.</li>\n<li>Offboard-Infrastruktur: Piktogramme für „Server“ (vom Festplatten-/Box-Symbol zum Server-Rack) und „Cloud“ (vektorbasierte Wolke) optisch überarbeitet; Server-Beschriftung neu platziert.</li>\n</ul>"}, {"from": "FIG-05a378b455e1e95b", "to": "FIG-0d53791d62cba4bd", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0d53791d62cba4bd", "to": "FIG-a621a6f5c59374d8", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a621a6f5c59374d8", "to": "FIG-19e42b923cfed040", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-19e42b923cfed040", "to": "FIG-efbdb9bac2d02a88", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
